11	const sha = x => crypto.createHash('sha256').update(x).digest('hex');
12	let input = null; const at = args.indexOf('--input');
13	if (at >= 0) { const file = path.resolve(args[at + 1]); const bytes = fs.readFileSync(file); fs.writeFileSync(path.join(dir, 'input.raw.json'), bytes, { flag: 'wx' }); input = { file, sha256: sha(bytes) }; }
14	const projectAt = args.indexOf('--project'), stateFile = projectAt < 0 ? null : path.resolve(args[projectAt + 1], '.writer/state.json');
15	function snap(name) { if (!stateFile || !fs.existsSync(stateFile)) return null; const bytes = fs.readFileSync(stateFile); fs.writeFileSync(path.join(dir, name), bytes, { flag: 'wx' }); return sha(bytes); }
16	const before = snap('before-state.json'), start = Date.now();
17	if (exe === 'npm.cmd' && args.some(x => !/^[A-Za-z0-9:_-]+$/.test(x))) throw Error('Unsafe npm arguments');
18	const actualExe = exe === 'npm.cmd' ? process.env.ComSpec : exe;
19	const actualArgs = exe === 'npm.cmd' ? ['/d', '/c', 'npm.cmd', ...args] : args;
20	const result = spawnSync(actualExe, actualArgs, { windowsHide: true, timeout: 300000, maxBuffer: 64 * 1024 * 1024 });
21	fs.writeFileSync(path.join(dir, 'stdout.raw.txt'), result.stdout ?? Buffer.alloc(0));
22	fs.writeFileSync(path.join(dir, 'stderr.raw.txt'), result.stderr ?? Buffer.alloc(0));
23	const meta = { exe, args, cwd: process.cwd(), started_at: new Date(start).toISOString(), elapsed_ms: Date.now() - start, exit_code: result.status, signal: result.signal, error: result.error?.message, input, before_state_sha256: before, after_state_sha256: snap('after-state.json') };
24	fs.writeFileSync(path.join(dir, 'result.json'), JSON.stringify(meta, null, 2) + '\n', { flag: 'wx' });
25	console.log(JSON.stringify(meta)); process.exitCode = result.status ?? 1;
